UPDATE DBF_DB_CONFIG
   SET USE_YN     = 0
     , UPDATED_AT = #{updatedAt,jdbcType=VARCHAR}
 WHERE DB_ALIAS   = #{dbAlias,jdbcType=VARCHAR}

UPDATE DBF_DB_CONFIG
   SET DB_ALIAS    = #{dbAlias,jdbcType=VARCHAR}
     , DB_TYPE     = #{dbType,jdbcType=VARCHAR}
     , DB_HOST     = #{dbHost,jdbcType=VARCHAR}
     , DB_PORT     = #{dbPort,jdbcType=INTEGER}
     , DB_NAME     = #{dbName,jdbcType=VARCHAR}
     , DB_SCHEMA   = #{dbSchema,jdbcType=VARCHAR}
     , DB_USER     = #{dbUser,jdbcType=VARCHAR}
     , DB_PASSWORD = #{dbPassword,jdbcType=VARCHAR}
     , USE_YN      = #{useYn,jdbcType=INTEGER}
     , UPDATED_AT  = #{updatedAt,jdbcType=VARCHAR}
 WHERE DB_CONFIG_ID = #{dbConfigId,jdbcType=INTEGER}
